// Main Schema


export type CashAnimationProps = Record<string, any>;

const CashAnimation: React.FC<CashAnimationProps> = ({
  backgroundColor = "#040805",
  transparentBackground = false,
  durationInSeconds = 10,
  neonColor = "#39ff14",
  cashScale = 1.0,
  backgroundCashScale = 1.0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Dynamic Background styling using the user's backgroundColor prop
  const backgroundStyle = transparentBackground
    ? "transparent"
    : `radial-gradient(circle, ${backgroundColor} 0%, #000000 100%)`;

  // Entrance animation for the 3D cash stack
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 14, mass: 1.2, stiffness: 75 },
  });

  const rotX = interpolate(entranceSpring, [0, 1], [45, 18]);
  const rotY = interpolate(entranceSpring, [0, 1], [-180, -32]);
  const rotZ = interpolate(entranceSpring, [0, 1], [-45, -12]);
  const translateZ = interpolate(entranceSpring, [0, 1], [-800, 0]);
  const scaleEntrance = interpolate(entranceSpring, [0, 1], [0.4, 1]);

  // Subtle continuous cinematic floating/drifting
  const idleSec = frame / fps;
  const idleX = Math.sin(idleSec * 1.2) * 1.5;
  const idleY = Math.cos(idleSec * 1.0) * 2;
  const idleZ = Math.sin(idleSec * 0.7) * 1;

  const finalRotX = rotX + idleX;
  const finalRotY = rotY + idleY;
  const finalRotZ = rotZ + idleZ;

  // Main 3D Cash stack coordinates
  const billWidth = 720;
  const billHeight = 310;
  const billDepth = 54; // Stack thickness

  // Sides styling for stack (representing layer of cash bills stacked up)
  const stackSideStyle: React.CSSProperties = {
    position: "absolute",
    boxSizing: "border-box",
    background: "repeating-linear-gradient(180deg, #1b2e1f, #1b2e1f 2px, #4d7a54 3px, #1b2e1f 4px)",
    boxShadow: `0 0 30px ${neonColor}55`,
    border: `1.5px solid ${neonColor}`,
    transition: "none",
  };

  // Generate deterministic floating background bill particles
  const floatingBillsCount = 14;
  const floatingBills = Array.from({ length: floatingBillsCount }).map((_, index) => {
    // Custom seed-based pseudo randomness to follow anti-flicker rules
    const seedX = (index * 0.13 + 0.05) % 1;
    const seedY = (index * 0.27 + 0.1) % 1;
    const seedZ = (index * 0.41 + 0.2) % 1;
    const seedSpeed = (index * 0.19 + 0.4) % 1;

    return { seedX, seedY, seedZ, seedSpeed, index };
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: transparentBackground ? "transparent" : backgroundColor,
        background: backgroundStyle,
        fontFamily: montserratFamily,
        overflow: "hidden",
        perspective: 1600,
      }}
    >
      {/* BACKGROUND FLOATING BILL PARTICLES */}
      {floatingBills.map((bill) => {
        const totalFrames = durationInSeconds * fps;
        const speedMultiplier = bill.seedSpeed * 1.2 + 0.4;
        const progress = (frame * speedMultiplier) % totalFrames;

        const startY = height * 1.2;
        const endY = -height * 0.2;
        const currentY = interpolate(progress, [0, totalFrames], [startY, endY]);

        // Drifting effect
        const drift = Math.sin((frame / 35) + bill.index) * 60;
        const currentX = bill.seedX * width + drift;

        const rotXVal = bill.seedX * 360 + frame * (bill.seedSpeed * 1.8);
        const rotYVal = bill.seedY * 360 + frame * (bill.seedSpeed * 1.4);
        const rotZVal = bill.seedZ * 360 + frame * (bill.seedSpeed * 1.0);

        const currentZ = bill.seedZ * 500 - 450;
        const particleScale = (bill.seedSpeed * 0.15 + 0.12) * backgroundCashScale;

        return (
          <div
            key={bill.index}
            style={{
              position: "absolute",
              left: currentX,
              top: currentY,
              width: 220,
              height: 94,
              transformStyle: "preserve-3d",
              transform: `translateZ(${currentZ}px) rotateX(${rotXVal}deg) rotateY(${rotYVal}deg) rotateZ(${rotZVal}deg) scale(${particleScale})`,
              opacity: interpolate(currentY, [-height * 0.1, height * 0.1, height * 0.9, height * 1.1], [0, 0.45, 0.45, 0]),
              pointerEvents: "none",
              transition: "none",
            }}
          >
            <div
              style={{
                width: "100%",
                height: "100%",
                backgroundColor: "#a4be9e",
                border: "2px solid #1e3321",
                borderRadius: "3px",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                fontSize: "14px",
                fontWeight: "bold",
                color: "#1e3321",
                boxShadow: "0 6px 15px rgba(0,0,0,0.4)",
              }}
            >
              $100
            </div>
          </div>
        );
      })}

      {/* 3D CASH STACK CONTAINER */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transformStyle: "preserve-3d",
          pointerEvents: "none",
        }}
      >
        <div
          style={{
            transformStyle: "preserve-3d",
            transform: `translateZ(${translateZ}px) rotateX(${finalRotX}deg) rotateY(${finalRotY}deg) rotateZ(${finalRotZ}deg) scale(${scaleEntrance * cashScale})`,
            width: billWidth,
            height: billHeight,
            position: "relative",
            transition: "none",
          }}
        >
          {/* FRONT FACE (Main bill) */}
          <div
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              transform: `translateZ(${billDepth / 2}px)`,
              backfaceVisibility: "hidden",
              transition: "none",
            }}
          >
            <DollarBillFront neonColor={neonColor} />
          </div>

          {/* BACK FACE */}
          <div
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              transform: `rotateY(180deg) translateZ(${billDepth / 2}px)`,
              backfaceVisibility: "hidden",
              transition: "none",
            }}
          >
            <DollarBillBack />
          </div>

          {/* LEFT FACE (Extrusion) */}
          <div
            style={{
              ...stackSideStyle,
              width: billDepth,
              height: billHeight,
              left: `calc(50% - ${billDepth / 2}px)`,
              transform: `rotateY(-90deg) translateZ(${billWidth / 2}px)`,
            }}
          />

          {/* RIGHT FACE (Extrusion with bright neon highlighting) */}
          <div
            style={{
              ...stackSideStyle,
              width: billDepth,
              height: billHeight,
              left: `calc(50% - ${billDepth / 2}px)`,
              transform: `rotateY(90deg) translateZ(${billWidth / 2}px)`,
              borderRight: `6px solid ${neonColor}`,
              filter: `drop-shadow(0 0 15px ${neonColor})`,
            }}
          />

          {/* TOP FACE (Extrusion) */}
          <div
            style={{
              ...stackSideStyle,
              width: billWidth,
              height: billDepth,
              top: `calc(50% - ${billDepth / 2}px)`,
              transform: `rotateX(90deg) translateZ(${billHeight / 2}px)`,
            }}
          />

          {/* BOTTOM FACE (Extrusion) */}
          <div
            style={{
              ...stackSideStyle,
              width: billWidth,
              height: billDepth,
              top: `calc(50% - ${billDepth / 2}px)`,
              transform: `rotateX(-90deg) translateZ(${billHeight / 2}px)`,
            }}
          />

          {/* BLUE STRAP / STRIP WRAPPING THE BILL STACK */}
          {/* Front Strap face */}
          <div
            style={{
              position: "absolute",
              width: "90px",
              height: billHeight + 2,
              left: "calc(50% - 45px)",
              top: -1,
              backgroundColor: "#182c58",
              border: "1.5px solid #0f1c3a",
              transform: `translateZ(${billDepth / 2 + 1}px)`,
              boxShadow: "0 0 10px rgba(0,0,0,0.5)",
              transition: "none",
            }}
          />
          {/* Back Strap face */}
          <div
            style={{
              position: "absolute",
              width: "90px",
              height: billHeight + 2,
              left: "calc(50% - 45px)",
              top: -1,
              backgroundColor: "#182c58",
              border: "1.5px solid #0f1c3a",
              transform: `rotateY(180deg) translateZ(${billDepth / 2 + 1}px)`,
              transition: "none",
            }}
          />
          {/* Top Strap face */}
          <div
            style={{
              position: "absolute",
              width: "90px",
              height: billDepth + 2,
              left: "calc(50% - 45px)",
              top: `calc(50% - ${billDepth / 2 + 1}px)`,
              backgroundColor: "#111f42",
              transform: `rotateX(90deg) translateZ(${billHeight / 2 + 1}px)`,
              transition: "none",
            }}
          />
          {/* Bottom Strap face */}
          <div
            style={{
              position: "absolute",
              width: "90px",
              height: billDepth + 2,
              left: "calc(50% - 45px)",
              top: `calc(50% - ${billDepth / 2 + 1}px)`,
              backgroundColor: "#111f42",
              transform: `rotateX(-90deg) translateZ(${billHeight / 2 + 1}px)`,
              transition: "none",
            }}
          />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CashAnimation;